import{_ as t,o,c as r,a2 as a}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"Introduction & Philosophy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1795176120000}'),n={name:"guide/introduction.md"};function i(s,e,d,l,c,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="introduction-philosophy" tabindex="-1">Introduction &amp; Philosophy <a class="header-anchor" href="#introduction-philosophy" aria-label="Permalink to &quot;Introduction &amp; Philosophy&quot;">​</a></h1><p>JetPack is a cross-platform <strong>Local Compute &amp; Native App Orchestrator</strong> designed to give modern web applications direct, sandboxed access to local CPU, RAM, and GPU hardware without requiring users to install Docker Desktop, virtual machines, or unmanaged Python toolchains.</p><h2 id="why-browser-only-webgpu-wasm-hit-a-wall" tabindex="-1">Why Browser-Only WebGPU &amp; WASM Hit a Wall <a class="header-anchor" href="#why-browser-only-webgpu-wasm-hit-a-wall" aria-label="Permalink to &quot;Why Browser-Only WebGPU &amp; WASM Hit a Wall&quot;">​</a></h2><p>WebAssembly (WASM) and WebGPU made significant strides in bringing computation to the browser, yet serious local AI inference, media transcoding, and native data processing encounter fundamental browser platform constraints:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Constraint</th><th style="text-align:left;">Browser WASM / WebGPU</th><th style="text-align:left;">JetPack Native Workers</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Memory Ceiling</strong></td><td style="text-align:left;"><code>wasm32</code> linear memory is capped at <strong>4 GiB</strong> (often ~2 GiB practical allocation per tab), making 7B–70B parameter models or large video buffers impractical.</td><td style="text-align:left;">Full host physical RAM and Unified Memory (<code>16 GiB–192+ GiB</code>), plus direct dedicated GPU VRAM.</td></tr><tr><td style="text-align:left;"><strong>GPU Ecosystem</strong></td><td style="text-align:left;">Limited to WebGPU/WGSL shaders; no access to vendor-tuned kernels such as <strong>NVIDIA CUDA / cuDNN / TensorRT</strong>, <strong>Apple Metal / MPS / MLX</strong>, <strong>AMD ROCm</strong>, or <strong>VideoToolbox / NVENC</strong>.</td><td style="text-align:left;">Direct native access to CUDA, Metal/MPS/MLX, ROCm, Vulkan, DirectML, and hardware video encoders when <code>permissions.gpu_access = true</code>.</td></tr><tr><td style="text-align:left;"><strong>CPU Threading &amp; SIMD</strong></td><td style="text-align:left;">Constrained by <code>SharedArrayBuffer</code> COOP/COEP headers, 128-bit WASM SIMD, and browser worker pool overhead.</td><td style="text-align:left;">Native multi-core threads, AVX2/AVX-512, NEON/AMX, and native C/C++/Rust/Python libraries.</td></tr><tr><td style="text-align:left;"><strong>Binary Ecosystem</strong></td><td style="text-align:left;">Cannot run existing native binaries (<code>ffmpeg</code>, <code>llama.cpp</code>, <code>postgres</code>, PyTorch C++ extensions) without brittle Emscripten ports.</td><td style="text-align:left;">Runs unmodified multi-arch native binaries (<code>PE/.exe</code>, <code>Mach-O</code>, <code>ELF</code>) and standalone Python via <code>uv</code>.</td></tr><tr><td style="text-align:left;"><strong>Storage &amp; Deduplication</strong></td><td style="text-align:left;">Duplicated Origin-Private File System (OPFS) blobs per origin; slow multi-GB downloads.</td><td style="text-align:left;">Shared Content-Addressable Storage (<code>blobs/sha256/</code>) with OS hardlinks and macOS APFS Copy-on-Write clones.</td></tr></tbody></table><h2 id="core-architectural-invariants" tabindex="-1">Core Architectural Invariants <a class="header-anchor" href="#core-architectural-invariants" aria-label="Permalink to &quot;Core Architectural Invariants&quot;">​</a></h2><p>Every component in JetPack adheres to seven strict architectural invariants:</p><ol><li><strong>Zero Virtual Machines</strong>: No WSL2, Hyper-V, Apple <code>Virtualization.framework</code>, Docker Daemon, or <code>containerd</code>. Workers execute directly on the host kernel as native processes.</li><li><strong>User-Space Only (No Admin / No Root)</strong>: Everything installs and executes inside the current unprivileged user&#39;s profile (<code>%APPDATA%\\JetPack</code>, <code>~/Library/Application Support/JetPack</code>, <code>~/.config/jetpack</code>). No UAC prompts and no <code>sudo</code>.</li><li><strong>Zero System Pollution</strong>: JetPack never writes to Windows <code>HKLM</code>, modifies global system <code>PATH</code>, installs system root CAs, or calls <code>/usr/bin/python3</code>.</li><li><strong>Rust as the Sole Gatekeeper</strong>: Browser tabs never connect directly to Python or C++ workers. Every external WebSocket connection terminates, authenticates, and decrypts inside <code>jetpack-daemon</code> (Rust).</li><li><strong>Default-Deny OS Kernel Sandboxing</strong>: Every worker runs inside a platform-native sandbox (<code>AppContainer</code> + <code>Job Objects</code> on Windows, <code>Seatbelt</code> on macOS, <code>bwrap</code> + <code>Landlock LSM</code> on Linux) with zero filesystem or network access unless explicitly granted.</li><li><strong>Userspace Network Proxy</strong>: Sandboxed workers have no direct network interface. Allowed outbound <code>host:port</code> endpoints are proxied through <code>jetpack-daemon</code> according to <code>permissions.network_allowlist</code>.</li><li><strong>Zero-Copy Binary Framing</strong>: No JSON payloads over WebSockets. Control plane and worker traffic use <code>[4B length] + [MsgPack Header] + [Raw Binary Payload]</code> protected by <code>X25519</code> + <code>ChaCha20-Poly1305</code>.</li></ol><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Explore the <a href="/guide/architecture">Three-Tier Architecture &amp; User Space Layout</a>.</li><li>Follow <a href="/guide/getting-started">Getting Started</a> to launch <code>jetpack-daemon</code> and the Control Center.</li><li>Review the <a href="/security/overview">Security Overview</a> for a full audit of JetPack&#39;s isolation boundaries.</li></ul>',10)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
